onload
VAR_CABLE_CLUB_STATE USING_MINIGAME CableClub_EventScript_ExitMinigameRoom
movements
Movement_AttendantFaceDown	face_down,end
Movement_AttendantFaceLeft	face_left,end
Movement_PlayerEnterMinigameRoom	left,up,up,up,end
